{
  "name": "builder_filtered_positive_diff_strict",
  "intuition": "Select pairs where the winner's objective is strictly better (lower) than the loser, enforcing winner < loser semantics for lower_is_better and ensuring nonnegative weights.",
  "implementation_hint": {
    "expects": [
      "objective",
      "log_prob"
    ],
    "returns": "PrefBatch",
    "mode": "pairwise"
  },
  "code": "def generated_builder(feature_cache, extra):\n    objective = feature_cache['objective']\n    # Compute pairwise differences: winner objective - loser objective\n    diff = objective[:, :, None] - objective[:, None, :]\n    # For lower_is_better, winner should have strictly lower objective than loser\n    mask = diff < 0\n    b_idx, winner_idx, loser_idx = mask.nonzero(as_tuple=True)\n    # Assign uniform positive weights since semantics require nonnegative weights\n    weight = diff[b_idx, winner_idx, loser_idx].abs()\n    # PrefBatch expects weight to be nonnegative, using abs of negative diff as positive weight\n    return PrefBatch(mode='pairwise', pair_idx=(b_idx.long(), winner_idx.long(), loser_idx.long()), weight=weight, meta={'builder': 'filtered_positive_diff_strict'})"
}
```

