{
  "name": "builder_all_pairs_tiezone",
  "intuition": "all pairs with tie-zone filtering to ignore near-ties",
  "hyperparams": {
    "geometry_family": "dense_all_pairs",
    "cap_family": "tiezone_capped",
    "weight_family": "uniform_none",
    "constraint_family": "tiezone_filter"
  },
  "operators_used": [
    "all_pairs",
    "clamp",
    "logical_and"
  ],
  "implementation_hint": {
    "expects": [
      "objective",
      "log_prob"
    ],
    "returns": "PrefBatch",
    "mode": "pairwise"
  },
  "code": "def generated_builder(feature_cache, extra):\n    objective = feature_cache['objective']\n    diff = objective[:, :, None] - objective[:, None, :]\n    mask = diff < 0\n    # Clamp differences at max -1.0 to cap extreme values\n    clamped_diff = diff.clamp(max=-1.0)\n    b_idx, winner_idx, loser_idx = mask.nonzero(as_tuple=True)\n    # Apply tie-zone filtering: only keep pairs where clamped difference < -0.2\n    tiezone_mask = clamped_diff[b_idx, winner_idx, loser_idx] < -0.2\n    b_idx = b_idx[tiezone_mask]\n    winner_idx = winner_idx[tiezone_mask]\n    loser_idx = loser_idx[tiezone_mask]\n    return PrefBatch(mode='pairwise', pair_idx=(b_idx, winner_idx, loser_idx), weight=None, meta={'builder': 'all_pairs_tiezone'})"
}

