{
  "name": "top_k_weighted_preferences",
  "intuition": "Construct pairwise preferences by selecting the top K pairs with the largest objective differences, which emphasize the most significant preference signals, and assign uniform weights to these pairs to focus on impactful decisions.",
  "hyperparams": {
    "geometry_family": "general",
    "cap_family": "topk",
    "weight_family": "uniform",
    "constraint_family": "none"
  },
  "operators_used": ["vector_diff", "topk", "pair_mask"],
  "implementation_hint": {
    "expects": ["objective", "log_prob"],
    "returns": "PrefBatch",
    "mode": "pairwise"
  },
  "code": "def generated_builder(feature_cache, extra):\n    objective = feature_cache['objective']\n    diff = objective[:, :, None] - objective[:, None, :]\n    abs_diff = diff.abs()\n    max_diff, _ = abs_diff.view(-1, abs_diff.shape[1] * abs_diff.shape[2]).max(dim=1)\n    topk_values, topk_indices = max_diff.topk(k=128, dim=1)\n    batch_size, _ = max_diff.shape\n    pair_idx_list = []\n    for b in range(batch_size):\n        indices = topk_indices[b]\n        winner_idx = indices // objective.shape[2]\n        loser_idx = indices % objective.shape[2]\n        b_idx = torch.full_like(winner_idx, b, dtype=torch.int64)\n        pair_idx_list.append(torch.stack([b_idx, winner_idx, loser_idx], dim=0))\n    pair_idx = torch.cat(pair_idx_list, dim=1)\n    weight = torch.ones(pair_idx.shape[1])\n    return PrefBatch(mode='pairwise', pair_idx=(pair_idx[0], pair_idx[1], pair_idx[2]), weight=weight, meta={'builder': 'top_k_weighted_preferences'})"
}

