{
  "name": "all_pairs_percentile_cap",
  "intuition": "all pairs with pairwise differences filtered by per-batch percentile cap to limit extreme pairs",
  "hyperparams": {
    "geometry_family": "dense_all_pairs",
    "cap_family": "percentile_capped",
    "weight_family": "uniform_none",
    "constraint_family": "tiezone_filter"
  },
  "operators_used": [
    "all_pairs",
    "clamp",
    "logical_and",
    "quantile"
  ],
  "implementation_hint": {
    "expects": [
      "objective",
      "log_prob"
    ],
    "returns": "PrefBatch",
    "mode": "pairwise"
  },
  "code": "def generated_builder(feature_cache, extra):\n    objective = feature_cache['objective']\n    diff = objective[:, :, None] - objective[:, None, :]\n    mask = diff < 0\n    b_idx, winner_idx, loser_idx = mask.nonzero(as_tuple=True)\n    diffs_selected = diff[b_idx, winner_idx, loser_idx]\n    # Compute 10th percentile per batch to set a cap\n    import torch\n    percentile_values = []\n    for b in diffs_selected.unique():\n        vals = diffs_selected[b_idx == b]\n        q_val = torch.quantile(vals, 0.1) if vals.numel() > 0 else float('-inf')\n        percentile_values.append(q_val)\n    percentile_values = torch.tensor(percentile_values, device=diff.device)\n    percentile_map = dict(zip(diffs_selected.unique().tolist(), percentile_values.tolist()))\n    # Map batch indices to percentiles\n    caps = torch.stack([percentile_map[int(b)] for b in b_idx.tolist()]).to(diff.device)\n    capped_mask = diffs_selected < caps\n    # Use tiezone filter threshold as well (< -0.2)\n    filtered_mask = capped_mask & (diffs_selected < -0.2)\n    b_idx = b_idx[filtered_mask]\n    winner_idx = winner_idx[filtered_mask]\n    loser_idx = loser_idx[filtered_mask]\n    return PrefBatch(mode='pairwise', pair_idx=(b_idx, winner_idx, loser_idx), weight=None, meta={'builder': 'all_pairs_percentile_cap'})"
}

