{
  "name": "objective_difference_with_dedup_and_clamp",
  "intuition": "Pairs selected by objective difference, filtered to remove duplicates using a symmetric mask deduplication, with clamped weights for robustness.",
  "hyperparams": {
    "geometry_family": "difference",
    "cap_family": "clamped_magnitude_cap",
    "weight_family": "clamped_magnitude_weight",
    "constraint_family": "dedup"
  },
  "operators_used": [
    "broadcast_sub",
    "clamp",
    "nonzero",
    "logical_and",
    "triu"
  ],
  "implementation_hint": {
    "expects": [
      "objective",
      "log_prob"
    ],
    "returns": "PrefBatch",
    "mode": "pairwise"
  },
  "code": "def generated_builder(feature_cache, extra):\n    objective = feature_cache['objective']  # (B, N)\n    B, N = objective.shape\n    diff = objective[:, :, None] - objective[:, None, :]  # (B, N, N)\n    # mask for strictly better pairs\n    mask = (diff < 0)\n    # generate symmetric deduplication mask - only keep pairs where loser index > winner index to remove duplicates\n    idx_i = torch.arange(N, device=objective.device)\n    idx_j = torch.arange(N, device=objective.device)\n    upper_tri_mask = idx_j[None, :] > idx_i[:, None]  # (N, N)\n    mask = mask.logical_and(upper_tri_mask.unsqueeze(0))  # (B, N, N)\n    b_idx, winner_idx, loser_idx = mask.nonzero(as_tuple=True)\n    raw_weights = (-diff[b_idx, winner_idx, loser_idx]).clamp(min=0)\n    max_w = raw_weights.max().clamp(min=1.0)\n    weights = raw_weights / max_w\n    weights = weights.clamp(min=0.05, max=0.95)\n    return PrefBatch(mode='pairwise', pair_idx=(b_idx, winner_idx, loser_idx), weight=weights, meta={'builder': 'objective_difference_with_dedup_and_clamp'})"
}

