{
  "name": "hybrid_pairs_topkcap_tiezone_004",
  "intuition": "Uses top-k cap per batch instance on pairs filtered by tie-zone to better control pair budget while preserving preference clarity.",
  "hyperparams": {
    "geometry_family": "dense_all_pairs",
    "cap_family": "topk_per_batch",
    "weight_family": "uniform_none",
    "constraint_family": "tie_zone_filter"
  },
  "operators_used": [
    "all_pairs",
    "tie_zone_filter",
    "topk_per_batch"
  ],
  "implementation_hint": {
    "expects": [
      "objective",
      "log_prob"
    ],
    "returns": "PrefBatch",
    "mode": "pairwise"
  },
  "code": "def generated_builder(feature_cache, extra):\n    objective = feature_cache['objective']\n    batch_size, n = objective.shape\n    gap = objective[:, :, None] - objective[:, None, :]\n    mask = gap > 1e-3\n    b_idx, winner_idx, loser_idx = mask.nonzero(as_tuple=True)\n    gap_vals = gap[b_idx, winner_idx, loser_idx]\n    max_pairs = int(extra.get('max_pairs', 128))\n    # Group pairs by batch index and select top-k (per batch) by gap\n    keep_mask = torch.zeros_like(gap_vals, dtype=torch.bool)\n    for b in range(batch_size):\n        idxs = (b_idx == b).nonzero(as_tuple=True)[0]\n        if idxs.numel() == 0:\n            continue\n        topk = min(max_pairs // batch_size + 1, idxs.numel())\n        topk_vals, topk_idxs = torch.topk(gap_vals[idxs], k=topk, largest=True, sorted=False)\n        keep_mask[idxs[topk_idxs]] = True\n    keep_idx = keep_mask.nonzero(as_tuple=True)[0]\n    b_idx = b_idx[keep_idx]\n    winner_idx = winner_idx[keep_idx]\n    loser_idx = loser_idx[keep_idx]\n    return PrefBatch(mode='pairwise', pair_idx=(b_idx, winner_idx, loser_idx), weight=None, meta={'builder': 'hybrid_pairs_topkcap_tiezone_004'})"
