{
  "name": "loss_logsigmoid_002_scale_invariant",
  "intuition": "Inject scale-invariance by normalizing the preference difference by the delta_regret magnitude, ensuring the loss is invariant to absolute scale of preferences.",
  "pseudocode": "norm_factor = clamp(abs(delta_regret), min=1e-6)\nloss = -logsigmoid(scale * (lpw - lpl) / norm_factor)\nloss = loss * weight\nreturn mean(loss)",
  "hyperparams": {
    "paradigm_family": "pairwise_margin",
    "signal_family": "delta_regret",
    "link_family": "logsigmoid",
    "agg_family": "mean",
    "constraint_family": "scale_invariance"
  },
  "operators_used": ["logsigmoid", "abs", "clamp", "div", "mul", "mean"],
  "implementation_hint": {
    "expects": ["log_prob_w", "log_prob_l", "weight", "delta_regret"],
    "returns": "scalar",
    "mode": "pairwise"
  },
  "code": "def generated_loss(batch, model_output, extra):\n    lpw = batch['log_prob_w']\n    lpl = batch['log_prob_l']\n    weight = batch.get('weight', None)\n    delta_regret = batch['delta_regret']\n    alpha = float(extra.get('alpha', extra.get('hyperparams', {}).get('alpha', 1.0)))\n    scale = float(extra.get('hyperparams', {}).get('scale', 0.6471628540177713))\n    norm_factor = ops.clamp(ops.abs(delta_regret), 1e-6, None)\n    x = alpha * scale * (lpw - lpl) / norm_factor\n    loss = -ops.logsigmoid(x)\n    if weight is not None:\n        loss = loss * weight\n    return loss.mean()"
}

{
  "name": "pairwise_pref_loss_logsig_sign",
  "intuition": "This loss encourages the model to assign higher probabilities to preferred pairs based on a combined signal of model confidence (logsigmoid of differences) and a preference indicator (sign of preference). Using logsigmoid stabilizes the gradient and emphasizes confident preferences, while the sign signal directs the penalty strength, ensuring the model learns to distinguish better pairs effectively.",
  "pseudocode": "loss = -sum(logsigmoid(preference_signal * (log_prob_w - log_prob_l)))",
