  "code": "def generated_loss(batch, model_output, extra):\n    log_prob_w = batch['log_prob_w']\n    log_prob_l = batch['log_prob_l']\n    preference_sign = ops.sign(batch.get('preference_indicator', ops.ones_like(log_prob_w)))\n    pair_diff = log_prob_w - log_prob_l\n    weighted_signal = preference_sign * pair_diff\n    loss = -ops.reduce_sum(ops.logsigmoid(weighted_signal) * batch['weight'])\n    return loss"
