{
  "name": "loss_tanh_delta_rank_scaled",
  "intuition": "A shift to a pairwise soft-margin loss using the hyperbolic tangent of a scaled difference in predicted log probabilities weighted by the normalized delta rank signal, encouraging preference alignment proportional to rank gap strength.",
  "pseudocode": "scale_score = tanh(scale * (log_prob_w - log_prob_l))\nweighted_rank = normalize(delta_rank) * scale_score\nloss = 1 - weighted_rank\nreturn mean(weighted_loss * weight)",
  "hyperparams": {
    "paradigm_family": "pairwise_soft_margin",
    "signal_family": "delta_rank",
    "link_family": "tanh",
    "agg_family": "mean",
    "constraint_family": "normalize"
  },
  "operators_used": ["tanh", "normalize", "mean", "mul", "sub"],
  "implementation_hint": {
    "expects": ["log_prob_w", "log_prob_l", "weight", "delta_rank"],
    "returns": "scalar",
    "mode": "pairwise"
  },
  "code": "def generated_loss(batch, model_output, extra):\n    lpw = batch['log_prob_w']\n    lpl = batch['log_prob_l']\n    weight = batch.get('weight', None)\n    delta_rank = batch['delta_rank']\n    scale = float(extra.get('hyperparams', {}).get('scale', 1.5))\n    scaled_diff = scale * (lpw - lpl)\n    tanh_score = ops.tanh(scaled_diff)\n    norm_rank = ops.normalize(delta_rank)\n    weighted_loss = 1 - norm_rank * tanh_score\n    if weight is not None:\n        weighted_loss = weighted_loss * weight\n    return weighted_loss.mean()"
}
